-- ---------- الأقسام (9) ----------
insert into public.departments (id,name,icon,descr,sort_order) values
  ('rel','إدارة العلاقات والتسويق','📣','التصاميم والإنتاج، روابط التبرّع والمتجر، الحملات، التغطيات الإعلامية، ملفات الداعمين، والموقع الإلكتروني.',1),
  ('inv','الإدارة المساندة','🛠️','الأوقاف والصيانة، النقل والحافلات، الحراسة والضيافة، والخدمات التقنية والاتصالات.',2),
  ('hr','إدارة الموارد البشرية','👥','التوظيف والمباشرة، الإجازات، الخطابات، بيانات الموظفين، والتظلمات.',3),
  ('fin','الإدارة المالية','💰','أوامر الصرف والعهد، سندات القبض، المناقلات، التقارير المالية، واعتماد الميزانيات.',4),
  ('ceo','مكتب الرئيس التنفيذي','🗂️','القرارات الإدارية، التوقيع والختم، المواعيد والمحاضر، الخطابات، والبرامج والمؤشرات.',5),
  ('edu_m','قسم تعليم البنين','📖','حلقات البنين: فتح الحلقات، التصاريح، الشهادات، رخص المعلمين، والمستلزمات التعليمية.',6),
  ('edu_f','قسم التعليم النسائي','🌸','المدارس والحلقات النسائية: فتح الحلقات، التصاريح والتكاليف، الشهادات، رخص المعلمات، والمستلزمات.',7),
  ('qa','قسم الجودة التعليمية','⭐','الزيارات الإشرافية، اختبارات الرخص، تقييم الأداء، اعتماد الخطط، ومعالجة ملاحظات الجودة.',8),
  ('vol','قسم التطوع','🤝','تسجيل المتطوعين، الفرص التطوعية، توثيق الساعات، والشهادات والشراكات.',9)
on conflict (id) do update set name=excluded.name, icon=excluded.icon,
  descr=excluded.descr, sort_order=excluded.sort_order;

